  if(e.target.dataset.saplingFreeEgo!=null){const[t,a]=e.target.dataset.saplingFreeEgo.split(':').map(Number);editor.turns[t].actions.forEach((action,index)=>action.saplingFreeEgo=index===a?e.target.checked:false);return persistAndRender();}
