  for(const[data,prop]of map){if(e.target.dataset[data]!=null){const[t,a]=e.target.dataset[data].split(':').map(Number),action=editor.turns[t].actions[a];action[prop]=e.target.value;if(prop==='memberKey'||prop==='mode')action.choice='';if(prop==='mode'&&!isEgoMode(action.mode))action.saplingFreeEgo=false;if(prop!=='target')for(const key of ['heads','coinFaces','sp','basePowerModifier','coinPowerModifier','finalPower','clashPowerModifier','levelDifference','targetDefenseLevel','attackWeightModifier','targetCount','reuse','sameFactionCount','rawDamage','rouletteFinalPower','targetSp','sinkingPotency','poisePotency','poiseCount','chargeCount','bloodfeastConsumed','critical','targetStaggered','targetPartDestroyed','targetHasNoSp','defeatedTarget'])delete action[key];if(prop==='mode'&&action.mode==='ego-forced-corrosion')action.sp=-45;return persistAndRender();}}
  if(e.target.dataset.actionCoinFace!=null){const[t,a,index]=e.target.dataset.actionCoinFace.split(':').map(Number),action=editor.turns[t].actions[a],skill=getActionSkill(action),profile=Rules.coinProfile(skill,{heads:action.heads,faces:action.coinFaces,sp:action.sp});action.coinFaces=[...profile.faces];action.coinFaces[index]=e.target.value==='H'?'H':'T';action.heads=action.coinFaces.filter(face=>face==='H').length;return persistAndRender();}
