  const numeric=[['actionHeads','heads'],['actionSp','sp'],['actionBasePowerModifier','basePowerModifier'],['actionCoinPowerModifier','coinPowerModifier'],['actionFinalPower','finalPower'],['actionClashPowerModifier','clashPowerModifier'],['actionLevelDifference','levelDifference'],['actionTargetDefenseLevel','targetDefenseLevel'],['actionAttackWeightModifier','attackWeightModifier'],['actionTargetCount','targetCount'],['actionReuse','reuse'],['actionPhysicalResistance','targetPhysicalResistance'],['actionAffinityResistance','targetAffinityResistance'],['actionSameFaction','sameFactionCount'],['actionRawDamage','rawDamage'],['actionRouletteFinalPower','rouletteFinalPower'],['actionTargetSp','targetSp'],['actionSinkingPotency','sinkingPotency'],['actionPoisePotency','poisePotency'],['actionPoiseCount','poiseCount'],['actionChargeCount','chargeCount'],['actionBloodfeastConsumed','bloodfeastConsumed']];
