$('#turnList').addEventListener('input',e=>{if(e.target.dataset.turnNote!=null){editor.turns[Number(e.target.dataset.turnNote)].note=e.target.value;saveDraft();}if(e.target.dataset.turnState!=null){editor.turns[Number(e.target.dataset.turnState)].stateChanges=e.target.value;renderResources();saveDraft();}if(e.target.dataset.actionTarget!=null){const[t,a]=e.target.dataset.actionTarget.split(':').map(Number);editor.turns[t].actions[a].target=e.target.value;saveDraft();}for(const[data,prop]of [['branchCondition','condition'],['branchResult','result']])if(e.target.dataset[data]!=null){const[t,b]=e.target.dataset[data].split(':').map(Number);editor.turns[t].branches[b][prop]=e.target.value;saveDraft();}});
